<!-- pages/qa/chat.vue -- TabBar唤起，调smartQaAPI.chat(POST /api/smart-qa/chat)，用户指令:标准UniApp分包架构 -->
<template><view class="p"><NavBar title="AI问答"/><s-v class="b" :st="st"><view v-if="!ms.length" class="w"><text class="wi">🤖</text><text class="wt">智能问答工作站</text><text class="wd">面向健康咨询、报告解读</text><view class="wp"><view v-for="(p,i) in prompts" :key="i" class="wc" @tap="send(p)"><text>{{p}}</text></view></view></view><view v-for="(m,i) in ms" :key="i" class="cm" :class="m.r==='u'?'cu':'cb'"><text class="mc">{{m.t}}</text></view><view v-if="th" class="cm cb"><text class="mth">思考中...</text></view></s-v><view class="ib"><input class="ci" v-model="iv" placeholder="输入健康问题..." @confirm="send(iv)"/><button class="cs" @tap="send(iv)" :disabled="!iv.trim()">发送</button></view><TabBar/></view></template>
<script setup>import{ref,nextTick}from'vue';import NavBar from'@/components/nav-bar.vue';import TabBar from'@/components/tab-bar.vue';import{smartQaAPI}from'@/api/smart-qa'
const prompts=['感冒药用药建议','高血压预防指南','糖尿病饮食计划','失眠综合诊防']
const ms=ref([]);const iv=ref('');const th=ref(false);const st=ref(0)
const sd=()=>nextTick(()=>{st.value=99999})
const send=async(t)=>{const x=t?.trim();if(!x)return;ms.value.push({r:'u',t:x});iv.value='';sd();th.value=true
try{const r=await smartQaAPI.chat('default',x,false);ms.value.push({r:'b',t:r?.data||r?.answer||JSON.stringify(r)});sd()}catch(e){ms.value.push({r:'b',t:'服务暂不可用'})}finally{th.value=false}}</script>
<style scoped>.p{min-height:100vh;background:#040b16;display:flex;flex-direction:column}.b{flex:1;padding:28rpx 28rpx 140rpx}.w{display:flex;flex-direction:column;align-items:center;padding:80rpx 0;text-align:center}.wi{font-size:80rpx;margin-bottom:24rpx}.wt{font-size:36rpx;font-weight:700;color:#f0f6ff;margin-bottom:14rpx}.wd{font-size:26rpx;color:rgba(200,218,242,0.65);margin-bottom:40rpx}.wp{display:flex;flex-wrap:wrap;gap:16rpx;justify-content:center}.wc{padding:16rpx 28rpx;border-radius:999rpx;background:rgba(8,15,26,0.6);border:1px solid rgba(125,211,252,0.12);font-size:24rpx;color:#70d6ff}.cm{max-width:80%;margin-bottom:24rpx;padding:20rpx 24rpx;border-radius:20rpx}.cu{margin-left:auto;background:linear-gradient(135deg,rgba(14,165,233,0.26),rgba(16,185,129,0.22));border:1px solid rgba(94,234,212,0.18)}.cb{background:rgba(8,20,35,0.78);border:1px solid rgba(125,211,252,0.08)}.mc{font-size:28rpx;color:#eef7ff;line-height:1.7}.mth{font-size:24rpx;color:#70d6ff}.ib{position:fixed;bottom:100rpx;left:0;right:0;padding:16rpx 28rpx;background:rgba(4,11,22,0.98);border-top:1px solid rgba(125,211,252,0.08);display:flex;gap:16rpx;align-items:center;padding-bottom:env(safe-area-inset-bottom)}.ci{flex:1;height:76rpx;padding:0 24rpx;border-radius:999rpx;background:rgba(255,255,255,0.06);color:#f0f6ff;font-size:28rpx;border:1px solid rgba(125,211,252,0.12)}.cs{height:76rpx;padding:0 32rpx;border-radius:999rpx;background:linear-gradient(135deg,#5eead4,#38bdf8);color:#032032;font-size:26rpx;font-weight:700;border:none}</style>
